// brain-eval electron stub — resolves ONLY for the eval bridge process
// (node module resolution finds this local node_modules first). Supplies
// the single electron surface the rag path touches: app.getPath.
// THE ONE RULE holds: no app/trainer/embeddings.bin writes happen here.
const os = require('os')
const path = require('path')
const userData = process.env.JT_STATE_DIR
  || path.join(os.homedir(), 'Library', 'Application Support', 'JakeTunes')
module.exports = {
  app: {
    getPath: (name) => {
      if (name === 'userData') return userData
      if (name === 'temp') return os.tmpdir()
      if (name === 'music') return path.join(os.homedir(), 'Music')
      return userData
    },
    isPackaged: false,
    getAppPath: () => path.resolve(__dirname, '../../../..'),
  },
}
